  if (typeof a === 'number' || typeof b === 'number') {
    return typeof a === 'number' && typeof b === 'number' && Number.isNaN(a) && Number.isNaN(b);
  }

  if (a === null || b === null || typeof a !== 'object' || typeof b !== 'object') {
    return false;
  }

  const typeA = Object.prototype.toString.call(a);
  const typeB = Object.prototype.toString.call(b);
  const aIsArray = Array.isArray(a);
  const bIsArray = Array.isArray(b);

  if (aIsArray !== bIsArray) {
    return false;
  }

  if (aIsArray) {
    if (a.length !== b.length) {
      return false;
    }

    for (let i = 0; i < a.length; i += 1) {
      if (!deepEqual(a[i], b[i])) {
        return false;
      }
    }

    return true;
  }

  const aIsDate = a instanceof Date || typeA === '[object Date]';
  const bIsDate = b instanceof Date || typeB === '[object Date]';

  if (aIsDate !== bIsDate) {
    return false;
  }

  if (aIsDate) {
    if (typeof a.getTime !== 'function' || typeof b.getTime !== 'function') {
      return false;
    }

    const timeA = a.getTime();
    const timeB = b.getTime();

    return timeA === timeB || (Number.isNaN(timeA) && Number.isNaN(timeB));
  }

  if (typeA !== typeB || typeA !== '[object Object]') {
    return false;
  }

  const keysA = Object.keys(a);
  const keysB = Object.keys(b);

  if (keysA.length !== keysB.length) {
    return false;
  }

  for (let i = 0; i < keysA.length; i += 1) {
    const key = keysA[i];

    if (!Object.prototype.hasOwnProperty.call(b, key) || !deepEqual(a[key], b[key])) {
      return false;
    }
  }

  return true;
}
